for (const [key, body] of Object.entries(hmiFields)) property(`hmi-${key}`, `HMI ${key}`, `setComponents[^]*\\b${key}\\b`, body, 'state-machine-simulation');
property('hmi-oled-mapping', 'OLED signal mappings', 'setComponents[^]*mapping.key', 'Map each OLED field to a declared live variable using its selector. Fields such as temperature, time, state and progress have different display interpretations. Verify values and units in Run mode; unset mappings display the component’s fallback values.', 'state-machine-simulation');
