action('hmi-rotate', 'Rotate encoder', 'rotate\\(', 'Use the clockwise/counterclockwise controls in Run mode to move through configured encoder values. Check the mapped variable and list order before interpreting the selected position. Edit mode configures the list rather than driving it.', 'state-machine-simulation');
action('hmi-select', 'Select HMI position', 'handleSelect\\(|handleClick', 'Select an HMI position in Run mode to exercise its configured value/mapping. In Edit mode select the component to configure it instead. Check the live variable and resulting model response after a selection.', 'state-machine-simulation');
