export const APP_HELP_FEATURES: HelpFeature[] = controls.map(control => ({
  id: control.id, label: control.label, topicId: control.id, sectionId: 'use', sourcePath: 'src/App.tsx', kind: control.kind, module: 'Application controls',
}));
export const APP_HELP_TOPICS: Record<string, HelpTopic> = Object.fromEntries(controls.map(control => [control.id, {
  title: control.label, category: control.kind === 'property' ? 'Properties' : 'Application controls',
  description: control.body, content: control.body,
  sections: [{ id: 'use', title: control.kind === 'property' ? 'Set this property' : 'Use this action', body: control.body, sources: ['src/App.tsx'] }],
  related: control.related ? [control.related] : [],
}]));
/** Exact semantic patterns supplied for contextual UI attributes and audit reconciliation. */
export const APP_HELP_MATCH_HINTS = controls.map(({id, pattern, label}) => ({id, pattern, label}));
export function matchAppHelpFeature(handler: string): HelpFeature | undefined {
  const hint = APP_HELP_MATCH_HINTS.find(({pattern}) => new RegExp(pattern).test(handler));
  return hint ? APP_HELP_FEATURES.find(feature => feature.id === hint.id) : undefined;
}
